import pyomo.environ as pyo

DATA = {
    "products": ["A", "B", "C", "D"],
    "profit_per_unit": {"A": 50, "B": 70, "C": 90, "D": 110},
    "linear_cost_per_unit": {"A": 30, "B": 40, "C": 50, "D": 60},
    "quadratic_divisor": 1000.0,
    "total_capacity": 1000,
    "min_units": {"A": 100},
    "max_units": {"A": 200},
    "budget": 50000,
    "breakpoints": [0, 200, 400, 600, 800, 1000],
}


def build_model(data=None):
    d = data or DATA
    products = d["products"]
    bps = d["breakpoints"]
    kset = list(range(len(bps)))
    max_units = max(bps)

    m = pyo.ConcreteModel()
    m.P = pyo.Set(initialize=products)
    m.K = pyo.Set(initialize=kset)

    m.x = pyo.Var(m.P, within=pyo.NonNegativeIntegers, bounds=(0, max_units))
    m.lam = pyo.Var(m.P, m.K, within=pyo.NonNegativeReals, bounds=(0, 1))

    def weight_sum_rule(m, p):
        return sum(m.lam[p, k] for k in kset) == 1
    m.weight_sum = pyo.Constraint(m.P, rule=weight_sum_rule)

    def def_x_rule(m, p):
        return m.x[p] == sum(bps[k] * m.lam[p, k] for k in kset)
    m.def_x = pyo.Constraint(m.P, rule=def_x_rule)

    def cap_rule(m):
        return sum(m.x[p] for p in products) <= d["total_capacity"]
    m.capacity = pyo.Constraint(rule=cap_rule)

    def min_rule(m, p):
        return m.x[p] >= d["min_units"].get(p, 0)
    m.min_demand = pyo.Constraint(m.P, rule=min_rule)

    def max_rule(m, p):
        return m.x[p] <= d["max_units"].get(p, max_units)
    m.max_demand = pyo.Constraint(m.P, rule=max_rule)

    def budget_rule(m):
        lin = sum(d["linear_cost_per_unit"][p] * m.x[p] for p in products)
        quad = sum((bps[k] ** 2 / d["quadratic_divisor"]) * m.lam[p, k]
                   for p in products for k in kset)
        return (lin + quad) <= d["budget"]
    m.budget = pyo.Constraint(rule=budget_rule)

    def obj_rule(m):
        rev = sum((d["profit_per_unit"][p] - d["linear_cost_per_unit"][p]) * m.x[p]
                  for p in products)
        quad = sum((bps[k] ** 2 / d["quadratic_divisor"]) * m.lam[p, k]
                   for p in products for k in kset)
        return rev - quad
    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    return m


